n = int(input())
a = list(map(int, input().split()))
q = int(input())
qs = list(map(int, input().split()))
def find(x):
    lo, hi = 0, n - 1
    while lo <= hi:
        m = (lo + hi) // 2
        if a[m] == x:
            return m
        if a[lo] <= a[m]:
            if a[lo] <= x < a[m]:
                hi = m - 1
            else:
                lo = m + 1
        else:
            if a[m] < x <= a[hi]:
                lo = m + 1
            else:
                hi = m - 1
    return -1
print("\n".join(str(find(x)) for x in qs))

n, h = map(int, input().split())
p = list(map(int, input().split()))
lo, hi = 1, max(p)
while lo < hi:
    m = (lo + hi) // 2
    if sum((x + m - 1) // m for x in p) <= h:
        hi = m
    else:
        lo = m + 1
