n, c = map(int, input().split())
xs = sorted(map(int, input().split()))
def ok(d):
    cnt, last = 1, xs[0]
    for x in xs[1:]:
        if x - last >= d:
            cnt += 1
            last = x
            if cnt >= c:
                return True
    return cnt >= c
lo, hi = 1, xs[-1] - xs[0]
while lo < hi:
    m = (lo + hi + 1) // 2
    if ok(m):
        lo = m
    else:
        hi = m - 1
print(lo)

n, k = map(int, input().split())
a = list(map(int, input().split()))
def parts(limit):
    cnt, cur = 1, 0
    for x in a:
        if cur + x > limit:
            cnt += 1
            cur = x
        else:
            cur += x
    return cnt
lo, hi = max(a), sum(a)
while lo < hi:
    m = (lo + hi) // 2
    if parts(m) <= k:
        hi = m
    else:
        lo = m + 1
print(lo)
